      powerHelps:[`passende Landwirtschafts-/Bergbaufertigkeiten`,`gute Werkzeuge`,`günstige Lage/Boden/Wetter`,`Anleitung durch Handbuch/Mentor`,`zusätzliche Arbeiter`,`Landkenntnis`,`Bauernkalender`],
