      powerHelps:[`Geisteskraft`,`passende magische Fertigkeiten/Items`,`Verhandlungsfertigkeiten`,`gemeinsame Ziele`,`Erfahrung mit dieser spezifischen Kreaturenart`,`für die Bindung dieser Kreaturenart geeignete Magie`,`gemeinsame Eigenschaften mit Ziel/Ursprung`,`bestehende Beziehung zum Ziel`,`Opfergaben`,`passende Autorität`,`Kenntnis des Geistergesetzes`],
